+	sysmon_q8p7_to_millicelsius(upper_reg, &upper_mc);
+	lower_mc = upper_mc - sysmon->temp_hysteresis;
+	sysmon_millicelsius_to_q8p7(&raw_val, lower_mc);
+
+	return regmap_write(sysmon->regmap, SYSMON_TEMP_TH_LOW, raw_val);
+}
